func TestReviewV4PrefsFailureRoutesAndLog(t *testing.T){d:=t.TempDir();s,e:=licensesrv.OpenStore(filepath.Join(d,"s.json"));if e!=nil{t.Fatal(e)};defer s.Close();real:=filepath.Join(d,"real.json");os.WriteFile(real,[]byte(`{}`),0600);link:=filepath.Join(d,"link.json");os.Symlink(real,link);t.Setenv("US_PRIVACY_PREFS_PATH",link);t.Setenv("US_PRIVACY_ERASE_ENABLED","1");t.Setenv("US_SESSION_SECRET",strings.Repeat("synthetic",8));var buf bytes.Buffer;old:=log.Writer();log.SetOutput(&buf);defer log.SetOutput(old);m:=newMux(licensesrv.Config{Now:time.Now},s);for _,c:=range []struct{path string;want int}{{"/account/privacy/erase/request",404},{"/account/privacy/erase/confirm",404},{"/account/privacy/preferences",503},{"/account/privacy/export",401},{"/healthz",200}}{r:=httptest.NewRequest("POST",c.path,strings.NewReader(`{}`));w:=httptest.NewRecorder();m.ServeHTTP(w,r);t.Logf("%s status=%d body=%s",c.path,w.Code,w.Body.String());if w.Code!=c.want{t.Fatalf("want %d",c.want)}};if !strings.Contains(buf.String(),"erase disabled"){t.Fatal("missing operator warning")};t.Logf("log=%s",buf.String())}
